  const jid =
    aComponents.getValue("room") + "@" + aComponents.getValue("server");
  const nick = aComponents.getValue("nick");

  let muc = this._mucs.get(jid);
  if (muc) {
    if (!muc.left) {
      // We are already in this conversation.
      return muc;
    } else if (!muc.chatRoomFields) {
